<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import AppIcon from '@/components/AppIcon.vue'
import PodcastCard from '@/components/PodcastCard.vue'
import PodcastDetail from '@/components/PodcastDetail.vue'
import EpisodeList from '@/components/EpisodeList.vue'
import { useAccountStore } from '@/stores/account'
import { useOfficialStore } from '@/stores/official'
import { useHistoryStore } from '@/stores/history'
const account = useAccountStore(), official = useOfficialStore(), history = useHistoryStore(), router = useRouter()
const selected = ref('')
const categories = computed(() => [...new Set(['全部', '商业', '科技', '文化', '生活', '故事', '音乐', ...official.discoverCategories.map(c => c.name)])].slice(0, 12))
const selectedPodcast = computed(() => official.discoverPodcasts.find(p => p.pid === selected.value))
async function browse(category: string): Promise<void> { if (!account.isLoggedIn) { await router.push('/official'); return }; selected.value = ''; await official.browseCategory(category === '全部' ? '播客' : category) }
async function open(pid: string): Promise<void> { selected.value = selected.value === pid ? '' : pid; if (selected.value) await official.loadEpisodes(pid) }
function loadInitial(): void { if (account.isLoggedIn && official.discoverStatus === 'idle') void official.browseCategory('播客') }
onMounted(loadInitial); watch(() => account.isLoggedIn, loadInitial)
</script>
<template><section class="page discover-page"><header class="page-heading"><div><span class="eyebrow">A LITTLE UNIVERSE OF SOUND</span><h1>发现好声音<span class="accent">.</span></h1><p>世界很大，值得听见的还有很多。</p></div><span class="small-label"><AppIcon name="headphones" :size="16" /> 戴上耳机，出发吧</span></header><section class="discovery-hero"><div class="hero-copy"><span class="hero-tag"><span></span>为好奇心，留一个位置</span><h2>把日常的片刻，<br />交给喜欢的声音。</h2><p>一个故事，一种新知，或一段有趣的对话。<br />在自己的节奏里，听见更大的世界。</p><div class="hero-actions"><RouterLink :to="account.isLoggedIn ? '/search' : '/official'" class="button primary">{{ account.isLoggedIn ? '寻找下一份灵感' : '连接我的小宇宙' }}<AppIcon name="arrow" :size="17" /></RouterLink><RouterLink to="/subscriptions" class="hero-link">从 RSS 开始<AppIcon name="chevron" :size="15" /></RouterLink></div></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 420 300" fill="none"><circle cx="229" cy="142" r="112" stroke="currentColor" stroke-opacity=".11" /><circle cx="229" cy="142" r="142" stroke="currentColor" stroke-opacity=".06" /><path d="M77 200c70 50 214 46 301-83" stroke="currentColor" stroke-opacity=".13" stroke-dasharray="4 7" /><g transform="rotate(-12 230 148)"><rect x="130" y="49" width="200" height="200" rx="31" fill="#E66E51" /><rect x="145" y="64" width="170" height="170" rx="22" fill="#F3B19B" /><circle cx="230" cy="149" r="68" fill="#343B40" /><circle cx="230" cy="149" r="57" stroke="#576067" /><circle cx="230" cy="149" r="46" stroke="#576067" /><circle cx="230" cy="149" r="34" stroke="#576067" /><circle cx="230" cy="149" r="22" fill="#FAE6CE" /><circle cx="230" cy="149" r="5" fill="#E66E51" /><path d="M303 81v60l-30 49" stroke="#FAE6CE" stroke-width="6" stroke-linecap="round" /><rect x="262" y="182" width="13" height="26" rx="4" transform="rotate(30 262 182)" fill="#FAE6CE" /></g><rect x="67" y="187" width="86" height="49" rx="16" fill="var(--hero-note)" /><path d="M87 216v-9m8 16v-23m8 29v-36m8 29v-22m8 16v-9m8 12v-15" stroke="#D5674C" stroke-width="3" stroke-linecap="round" /><circle cx="335" cy="61" r="6" fill="#ECAA63" /><path d="M91 87v14m-7-7h14M351 231v10m-5-5h10" stroke="#719F96" stroke-width="2" stroke-linecap="round" /></svg><span class="art-caption">GOOD SOUNDS. GOOD COMPANY.</span></div></section><div class="section-heading categories-heading"><div><span class="eyebrow">FOLLOW YOUR CURIOSITY</span><h2>从兴趣出发</h2></div><button v-if="account.isLoggedIn" class="text-button" :disabled="official.discoverStatus === 'loading'" @click="browse(official.discoverKeyword || '播客')"><AppIcon name="refresh" :size="15" />刷新</button></div><div class="category-tabs" aria-label="播客分类"><button v-for="category in categories" :key="category" type="button" :class="{ active: category === official.discoverKeyword || (category === '全部' && (!official.discoverKeyword || official.discoverKeyword === '播客')) }" @click="browse(category)">{{ category }}</button></div><template v-if="account.isLoggedIn"><p v-if="official.discoverStatus === 'loading'" class="loading-message" role="status">正在发现新的声音…</p><div v-else-if="official.discoverStatus === 'error'" class="notice error" role="alert">{{ official.discoverError }}<button class="text-button" @click="browse(official.discoverKeyword || '播客')">重试</button></div><p v-else-if="official.discoverStatus === 'empty'" class="empty-state compact">这个分类暂时没有找到播客，换个兴趣试试。</p><div v-if="official.discoverPodcasts.length" class="podcast-grid"><PodcastCard v-for="podcast in official.discoverPodcasts" :key="podcast.pid" :podcast="podcast" :active="selected === podcast.pid" @open="open" /></div><PodcastDetail v-if="selectedPodcast" :podcast="selectedPodcast" @close="selected = ''" /><section v-if="official.discoverEpisodes.length" class="section-block"><header class="section-heading"><h2>也许你会想听</h2><span class="muted">来自当前分类的单集</span></header><EpisodeList :items="official.discoverEpisodes" /></section></template><div v-else class="guest-grid"><RouterLink to="/official" class="feature-card"><span class="feature-icon peach"><AppIcon name="discover" :size="25" /></span><div><h3>你的兴趣，自有回响</h3><p>登录后按分类探索播客，找回你订阅的声音。</p><span class="feature-link">登录并探索<AppIcon name="arrow" :size="15" /></span></div></RouterLink><RouterLink to="/subscriptions" class="feature-card"><span class="feature-icon sage"><AppIcon name="rss" :size="25" /></span><div><h3>好播客，不止一种入口</h3><p>添加 RSS 订阅，无需登录，也能自在收听。</p><span class="feature-link">添加第一个订阅<AppIcon name="arrow" :size="15" /></span></div></RouterLink></div><footer class="page-footnote"><span class="footnote-line"></span><span>{{ history.entries.length ? '已经留下 ' + history.entries.length + ' 段收听足迹，去历史页接着听吧。' : '声音会陪你，把平常的日子过得有意思。' }}</span><span class="footnote-line"></span></footer></section></template>
